def shell(title, description, path, body, script='', article=False):
    url = 'https://celesys.ai'+path
    schema = {'@context':'https://schema.org', '@type':'Article' if article else 'WebPage', 'name':title, 'description':description, 'url':url}
    if article: schema.update(headline=title, author={'@type':'Organization','name':'Celesys AI'})
    schema_json = json.dumps(schema).replace('<', '\\u003c')
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'+f'''<title>{escape(title)} | Celesys AI</title><meta name="description" content="{escape(description)}"><link rel="canonical" href="{url}"><meta name="theme-color" content="#0b151b"><meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(description)}"><meta property="og:url" content="{url}"><meta name="twitter:card" content="summary_large_image"><meta property="og:image" content="https://celesys.ai/og-image.png"><meta name="twitter:image" content="https://celesys.ai/og-image.png"><meta name="google-site-verification" content="googleb6e1e80f88761fcc"><script src="/discovery/analytics.js" defer></script><link rel="stylesheet" href="/discovery/site.css"><script type="application/ld+json">{schema_json}</script>'''+(f'<script src="{script}" defer></script>' if script else '')+'</head><body><a class="skip" href="#main">Skip to content</a><header>'+NAV+'</header><main id="main">'+body+'''</main><footer><div><strong>CELESYS AI</strong><p>Understand the evidence. Own your decision.</p></div><div><a href="/methodology">Data & methodology</a><a href="/about">About</a><a href="/privacy">Privacy</a><a href="/terms">Terms</a><a href="/disclaimer">Risk disclosure</a><a href="/contact">Contact</a></div><p class="muted">Educational research, not personalized investment advice. Market data availability and timeliness vary. Options can lose their entire premium; some strategies carry greater risk. No broker orders are placed by these workspaces.</p></footer></body></html>'''


