@router.get('/options/{market}', response_class=HTMLResponse)
def options_page(market: str):
    if market not in ('india','us'): raise HTTPException(404, 'Market not found')
    region = 'IN' if market == 'india' else 'US'
    title = 'India option chain: NIFTY, BANKNIFTY & SENSEX' if region == 'IN' else 'US stock & ETF option-chain explorer'
    description = 'Compare calls and puts by expiry, strike, bid/ask, open interest and implied volatility. Provider availability and timestamp limitations are visible.'
    body = f'''<section class="section" id="chain-app" data-region="{region}"><p class="eyebrow">OPTIONS WORKSPACE / INDIA + UNITED STATES</p><h1>{title}</h1><p class="lead">A clearer view of contracts. A careful view of the evidence.</p><div class="market-tabs"><a class="{'active' if region == 'IN' else ''}" href="/options/india">India · INR</a><a class="{'active' if region == 'US' else ''}" href="/options/us">United States · USD</a></div><form id="chain-form" class="chain-toolbar"><label>Underlying<select id="india-symbol" {'hidden disabled' if region == 'US' else ''}><option>NIFTY</option><option>BANKNIFTY</option><option>FINNIFTY</option><option>SENSEX</option></select><input id="us-symbol" aria-label="US stock or ETF ticker" maxlength="10" value="SPY" {'hidden disabled' if region == 'IN' else ''} pattern="[A-Za-z][A-Za-z0-9.]{{0,9}}"></label><label>Expiry<select id="expiry"><option value="">Nearest available</option></select></label><button class="button" id="load-chain">Load option chain ↗</button></form><p class="muted">{'India index contracts; expiry choices come from the provider.' if region == 'IN' else 'Try SPY, QQQ, AAPL or NVDA. Stock/ETF snapshots; verify contract deliverables with your broker.'} No automatic refresh or broker orders.</p><div class="status" id="chain-status" role="status" aria-live="polite">No data requested yet. Load a chain to check availability.</div><div id="chain-meta" class="muted"></div><div class="summary" id="chain-summary" hidden></div><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable option chain"><table id="chain-table" hidden><caption>Call and put snapshot. Prices per underlying unit; contract costs depend on the multiplier. OI units follow the provider.</caption><thead><tr><th scope="col">Call OI</th><th scope="col">Call ΔOI</th><th scope="col">Call bid / ask</th><th scope="col">Call IV %</th><th scope="col">Strike</th><th scope="col">Put IV %</th><th scope="col">Put bid / ask</th><th scope="col">Put ΔOI</th><th scope="col">Put OI</th><th scope="col">Details</th></tr></thead><tbody id="chain-rows"></tbody></table></div><div class="callout"><h2>Read the context, not just the numbers.</h2><p>OI is not a direction signal. IV is not a prediction. A recent fetch does not make a quote current. Missing values stay missing; provider snapshots are not executable prices.</p><a href="/learn/how-to-read-option-chain">How to read this table →</a></div><div class="cards"><a class="card" href="/learn/open-interest-and-pcr"><h3>What does PCR really mean?</h3><p>Learn why coverage, expiry and units matter.</p></a><a class="card" href="/methodology"><h3>Where does this data come from?</h3><p>Read the source, freshness and coverage limitations.</p></a><a class="card" href="/trading/"><h3>Put the underlying in context</h3><p>Review price structure and data checks in the Trading Desk.</p></a></div></section>'''
    return shell(title, description, '/options/'+market, body, '/discovery/options.js')


def attach_discovery(app, india_token_supplier=None, dashboard_supplier=None, trading_supplier=None, options_supplier=None):
    if any(getattr(r,'path',None)=='/learn' for r in app.routes): return
    from option_chain import router as chains
    from research_agents import router as agents, configure_dashboard
    if dashboard_supplier: configure_dashboard(dashboard_supplier)
    from existing_engines import configure, router as existing
    configure(trading_supplier, options_supplier)
    app.include_router(existing)
    app.include_router(agents)
    app.include_router(router)
    app.include_router(chains)
    app.mount('/discovery', StaticFiles(directory=str(ROOT/'discovery')), name='discovery')

